changeSet.sql:
UPDATE bookings SET status = 'CONFIRMED', hold_expires_at = NULL WHERE source = 'WALK_IN' AND status = 'PENDING_PAYMENT';
UPDATE bookings SET hold_expires_at = NULL WHERE source = 'WALK_IN' AND status IN ('CONFIRMED', 'CHECKED_IN', 'COMPLETED') AND hold_expires_at IS NOT NULL;
UPDATE time_slots slot SET status = 'BOOKED' WHERE slot.status = 'LOCKED' AND EXISTS ( SELECT 1 FROM bookings booking WHERE booking.venue_court_id = slot.venue_court_id AND booking.play_date = slot.date AND booking.start_time = slot.start_time AND booking.end_time = slot.end_time AND booking.source = 'WALK_IN' AND booking.status IN ('CONFIRMED', 'CHECKED_IN', 'COMPLETED') );
